import{z as B,x as i,o,c,q as r,j as s,D as e,d as E,s as n,S as A,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"工具协议深钻","description":"","frontmatter":{"title":"工具协议深钻","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-tool-protocol-deep.md","filePath":"llm/agent-tool-protocol-deep.md","lastUpdated":1791413859000}'),m={name:"llm/agent-tool-protocol-deep.md"};function d(h,a,p,f,C,D){const t=i("Mermaid");return o(),c("div",null,[a[2]||(a[2]=r('<h1 id="工具协议深钻" tabindex="-1">工具协议深钻 <a class="header-anchor" href="#工具协议深钻" aria-label="Permalink to &quot;工具协议深钻&quot;">​</a></h1><div class="epigraph"><p>工具描述不是文档，是提示词的一部分；schema 里每一次措辞修改，都是一次条件分布的移动。</p><footer>—— 据 Schick et al., Toolformer, NeurIPS 2023；Anthropic，Model Context Protocol 规范（2024）整理</footer></div><p><a href="/llm/agent-loop-design-space">上一课</a>把循环立成五根轴，其中「模型选动作」这一环在本课下钻：动作不是自由文本，是走协议的事件。主干已有 <a href="/llm/function-calling">function calling</a> 的信封格式与 <a href="/llm/mcp">MCP</a> 的宿主—服务器生态；本课把协议当成接口契约来审——schema 即提示、回填即合同、错误通道即自纠的原料。训练侧怎么让模型学会这套协议（<a href="/llm/tool-call-sft">Function calling 训练</a>、<a href="/llm/tool-schema-sft">工具 schema 训练</a>）只引用不重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模型看到工具定义后才决定调不调、怎么调，所以 schema 的每一行都直接进入条件分布。<span class="marginnote">schema（模式）就是给参数立的规矩：字段叫什么、什么类型、哪些必填哪些可选——像快递下单表单，收件人、电话、地址一栏一格，格式定死了才不会把「电话」填进「地址」。工具 schema 就是给模型看的这张表单。</span>第一类失败是描述漂移：文档说参数可选，实现却必填；描述写得像开发者备注，模型按字面理解就传错。第二类是清单膨胀：把几十个工具静态写进每次请求，上下文被说明书占满，真正相关的用法描述反而被稀释——Gorilla 的结论之一就是让模型按需检索文档，而不是全量背下 API。第三类是回填混乱：同一轮并行发起多个调用时，结果必须按调用 ID 各自配对；错配之后模型把 A 的输出当成 B 的观察，后续推理整条链被污染。第四类是大结果：一次读取返回几千行，全文回填会挤占轨迹预算（处置策略是<a href="/llm/agent-context-strategies">上下文管理策略</a>的主题，协议层先要留出「落盘给句柄」的表达）。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议分四层来抠。<strong>schema 层</strong>：命名空间防冲突（同义工具来自不同服务器时必须可区分）；描述写成给新同事的操作手册——何时用、何时不该用、参数举例；能用枚举就不用自由字符串，能少一个参数就少一个。<span class="marginnote">枚举（enum）就是把参数限制成固定几个选项。数字实例：参数「城市」若不限枚举，模型可能传「上海」「魔都」「Shanghai」三种写法；写成枚举 [「北京」,「上海」,「广州」]，第四种写法在解码层就根本出不来，这类参数错误被整类消灭。</span><strong>信封层</strong>：调用与结果按 ID 严格配对，并行调用各自独立回填；结构化参数用 <a href="/llm/json-schema-decode">JSON / 结构化输出</a>的约束通道在解码层保证合法，而不是靠模型自觉。<strong>结果层</strong>：成功结果回填数据，失败结果回填错误原文——stderr、校验消息、HTTP 状态码原样给模型，让它有机会修正参数重试；重试设上限，防振荡。<strong>治理层</strong>：schema 变更是破坏性变更，走灰度；权限随工具走，<a href="/llm/mcp-design">MCP 协议设计</a>按服务器隔离鉴权是这层的基础。</p>',7)),(o(),s(A,null,{default:e(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCH%5B%22schema%20%E5%B1%82%EF%BC%9A%E5%A3%B0%E6%98%8E%E4%B8%8E%E6%8F%8F%E8%BF%B0%22%5D%20--%3E%20ENV%5B%22%E4%BF%A1%E5%B0%81%E5%B1%82%EF%BC%9A%E8%B0%83%E7%94%A8%E4%B8%8E%20ID%20%E9%85%8D%E5%AF%B9%22%5D%0A%20%20ENV%20--%3E%20EXEC%5B%22%E6%89%A7%E8%A1%8C%E5%B1%82%EF%BC%9A%E6%B2%99%E7%AE%B1%E8%BF%90%E8%A1%8C%22%5D%0A%20%20EXEC%20--%3E%20RES%7B%22%E6%88%90%E5%8A%9F%3F%22%7D%0A%20%20RES%20--%3E%7C%22%E6%98%AF%22%7C%20BACK%5B%22%E7%BB%93%E6%9E%9C%E5%9B%9E%E5%A1%AB%EF%BC%88%E5%A4%A7%E8%BE%93%E5%87%BA%E8%90%BD%E7%9B%98%E7%BB%99%E5%8F%A5%E6%9F%84%EF%BC%89%22%5D%0A%20%20RES%20--%3E%7C%22%E5%90%A6%22%7C%20ERR%5B%22%E9%94%99%E8%AF%AF%E5%8E%9F%E6%96%87%E5%9B%9E%E5%A1%AB%20%2B%20%E9%87%8D%E8%AF%95%E4%B8%8A%E9%99%90%22%5D%0A%20%20ERR%20--%3E%20ENV%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[E("为什么错误回喂是控制信号：参数校验失败时，把「哪个字段、违反了什么约束」的原文还给模型，等价于给了一次有方向的文本梯度——模型下一轮的修正是条件化的，不是再掷一次骰子。"),l("span",{class:"marginnote"},"「文本梯度」是类比：训练时梯度告诉参数往哪个方向调；把「city 字段拼写不合法，应为拼音」这样的错误原文回给模型，等于告诉它下一轮往哪个方向修——比只回一句「调用失败」让它盲试要省好几轮。"),E("这与 Toolformer 的教训同源：模型能自学调用，但自学出来的格式必须被协议固定，否则每次采样的表面形式都在漂。回填错配则是配对机制的意义所在：并行调用共享一轮对话，唯一能把「哪个结果属于哪个请求」钉死的就是调用 ID；这层出错的排障代价远高于省掉它的便利。")],-1)),(o(),s(A,null,{default:e(()=>[n(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%8C%E4%B8%80%E8%BD%AE%E5%B9%B6%E8%A1%8C%E5%8F%91%E8%B5%B7%E4%B8%A4%E4%B8%AA%E8%B0%83%E7%94%A8%22%5D%20--%3E%20C1%5B%22call_001%EF%BC%9A%E6%9F%A5%E5%A4%A9%E6%B0%94%22%5D%0A%20%20A%20--%3E%20C2%5B%22call_002%EF%BC%9A%E6%9F%A5%E6%97%A5%E5%8E%86%22%5D%0A%20%20C1%20--%3E%20R1%5B%22%E7%BB%93%E6%9E%9C%E6%8C%89%20call_001%20%E9%85%8D%E5%AF%B9%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20C2%20--%3E%20R2%5B%22%E7%BB%93%E6%9E%9C%E6%8C%89%20call_002%20%E9%85%8D%E5%AF%B9%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20R1%20--%3E%20OK%5B%22%E6%A8%A1%E5%9E%8B%E6%8E%A8%E7%90%86%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20R2%20--%3E%20OK%0A%20%20R1%20-.%20%22%E9%94%99%E9%85%8D%EF%BC%9A%E5%A4%A9%E6%B0%94%E7%BB%93%E6%9E%9C%E7%AD%94%E4%BA%86%E6%97%A5%E5%8E%86%E9%97%AE%E9%A2%98%22%20.-%3E%20BAD%5B%22%E5%90%8E%E7%BB%AD%E6%95%B4%E6%9D%A1%E6%8E%A8%E7%90%86%E9%93%BE%E8%A2%AB%E6%B1%A1%E6%9F%93%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">幂等性是协议层对重试的授权：查询类工具天然可重试，写入类工具必须有幂等键，否则「错误原文回喂后重试」会把一次失败放大成两次下单。工具描述里应写明幂等语义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>执行在哪里跑、能碰什么文件与网络，是沙箱问题（<a href="/llm/tool-sandbox">工具沙箱</a>），本课只管「执行前后事件如何交换」。跨组织的代理互调不是工具协议而是服务协议（<a href="/llm/a2a-protocol">A2A 协议</a>），发现与信任模型不同。工具数量大到单清单装不下时，动态发现与按需加载涉及检索与权限，围栏视角在<a href="/llm/agent-guardrails">安全围栏</a>补全。schema 的措辞优化没有终点：它是对条件分布的持续调参，必须与提示一起进版本管理——这条约定在<a href="/llm/agent-regression-rollback">回归测试与版本回滚</a>兑现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>schema 即提示：描述的措辞直接改调用分布，改 schema 就是改模型行为。</li><li>调用与结果按 ID 严格配对；并行调用错配会污染整条推理链。</li><li>失败要回喂错误原文并设重试上限；回喂是方向性信号，无上限是振荡。</li><li>大结果落盘给句柄，回填句柄不回填全文。</li><li>schema 变更走破坏性变更流程，权限按服务器隔离。</li><li>出处：据 Schick et al., Toolformer, NeurIPS 2023 与 Anthropic MCP 规范（2024）的协议口径整理。</li></ul>',5))])}const F=B(m,[["render",d]]);export{u as __pageData,F as default};
